<script setup lang="ts">
import { ArrowUpRight, CalendarDays, Clock3, UsersRound, Equal, AlertCircle, Plus, Printer } from '@lucide/vue'
import { formatHours, monthLabel } from '../domain/calendar'
import { clockLabel, planShifts, shiftHours } from '../domain/shifts'
const w = useWorkspace(), newMonth = ref(false)
const total = computed(() => w.summaries.value.reduce((n, r) => n + r.knownHours, 0))
const filled = computed(() => w.summaries.value.reduce((n, r) => n + r.workDays + r.offDays + r.leaveDays + r.notStartedDays, 0))
const currentErrors = computed(() => w.issues.value.filter(i => !i.historical && i.severity === 'error'))
const chartMax = computed(() => Math.max(1, ...w.summaries.value.map(r => r.knownHours)))
const codes = computed(() => w.data.value && w.plan.value ? planShifts(w.data.value, w.plan.value).filter(s => ['PI', 'SI', 'NI', 'PSI', 'MI'].includes(s.code)) : [])
</script>
<template>
  <PageHeading title="Ringkasan jadwal" subtitle="Satu tempat untuk memantau dinas, beban kerja, dan kebutuhan layanan." eyebrow="Selamat datang"><MonthSelect/><NuxtLink to="/jadwal" class="btn btn-primary"><CalendarDays :size="16"/>Buka jadwal</NuxtLink></PageHeading>
  <template v-if="w.plan.value">
    <div class="mb-7 grid grid-cols-2 gap-3 xl:grid-cols-4 xl:gap-5">
      <div v-for="card in [{ label: 'Dokter dalam jadwal', value: w.summaries.value.length, unit: 'orang', icon: UsersRound, note: `${w.summaries.value.filter(r => r.doctor.unit === 'anak').length} khusus ruang anak` }, { label: 'Total jam terjadwal', value: formatHours(total), unit: 'jam', icon: Clock3, note: `${filled} isian dinas tercatat` }, { label: 'Selisih jam rotasi penuh', value: formatHours(w.balance.value.spread), unit: 'jam', icon: Equal, note: `${w.balance.value.rows.length} dokter dengan ketersediaan sama` }, { label: 'Perlu penyesuaian', value: currentErrors.length, unit: 'catatan', icon: AlertCircle, note: 'Riwayat ditampilkan terpisah' }]" :key="card.label" class="panel p-4 sm:p-5"><div class="mb-5 flex items-center justify-between"><p class="text-xs font-medium text-slate-500">{{ card.label }}</p><component :is="card.icon" :size="18" class="text-brand-600"/></div><p class="flex flex-wrap items-baseline gap-1.5 text-[28px] leading-none font-semibold tracking-tight">{{ card.value }}<span class="text-xs font-normal text-slate-400">{{ card.unit }}</span></p><p class="mt-3 text-[11px] leading-relaxed text-slate-400">{{ card.note }}</p></div>
    </div>
    <div class="grid gap-6 xl:grid-cols-[1.5fr_1fr]">
      <section class="panel overflow-hidden"><div class="flex items-center justify-between border-b border-slate-100 px-6 py-5"><div><h2 class="text-sm font-semibold">Jam kerja per dokter</h2><p class="mt-1 text-xs text-slate-400">{{ monthLabel(w.activeMonth.value) }} · jam aktual dari jadwal</p></div><NuxtLink to="/rekap" class="text-xs font-semibold text-brand-700">Lihat rekap <ArrowUpRight :size="14" class="inline"/></NuxtLink></div><div class="space-y-4 p-6"><div v-for="r in w.summaries.value" :key="r.doctor.id" class="grid grid-cols-[108px_1fr_44px] items-center gap-3 sm:grid-cols-[132px_1fr_52px]"><div><p class="truncate text-xs font-medium">{{ r.doctor.name }}</p><p v-if="!r.comparable" class="mt-0.5 text-[10px] text-slate-400">{{ r.doctor.unit === 'anak' ? 'Ruang anak' : r.leaveDays ? `${r.leaveDays} hari cuti` : 'Mulai bulan ini' }}</p></div><div class="h-2.5 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full" :class="r.comparable ? 'bg-brand-500' : 'bg-lime-soft'" :style="{ width: `${r.knownHours / chartMax * 100}%` }"/></div><p class="text-right text-xs font-semibold tabular-nums">{{ formatHours(r.totalHours) }}</p></div></div><p class="border-t border-slate-100 bg-slate-50/50 px-6 py-4 text-[11px] leading-relaxed text-slate-400">Pemerataan membandingkan dokter rotasi dengan ketersediaan sebulan penuh. Cuti, dokter baru, dan ruang anak dihitung sesuai dinasnya.</p></section>
      <section class="panel p-6"><div class="mb-5 flex items-center justify-between"><h2 class="text-sm font-semibold">Pemeriksaan jadwal</h2><span class="tag bg-slate-100 text-slate-500">{{ w.issues.value.length }} catatan</span></div><IssueList :issues="w.issues.value" :limit="5"/><NuxtLink to="/jadwal" class="btn btn-secondary mt-5 w-full">Periksa jadwal</NuxtLink></section>
    </div>
    <div class="mt-6 grid gap-6 lg:grid-cols-[1.5fr_1fr]"><section class="panel p-6"><div class="mb-5 flex items-center justify-between"><h2 class="text-sm font-semibold">Jam dinas bulan ini</h2><NuxtLink to="/kode-dinas" class="text-xs font-semibold text-brand-700">Semua kode</NuxtLink></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-5"><div v-for="s in codes" :key="s.code" class="rounded-xl border border-slate-100 p-3"><p class="text-sm font-semibold text-brand-700">{{ s.code }}</p><p class="mt-2 text-[11px] text-slate-500">{{ clockLabel(s) }}</p><p class="mt-1 text-xs font-semibold">{{ shiftHours(s) }} jam</p></div></div></section><section class="relative overflow-hidden rounded-2xl bg-brand-800 p-6 text-white"><span class="absolute -right-7 -bottom-14 h-44 w-44 rounded-full border-[22px] border-white/5"/><p class="text-sm font-semibold">Siap dibagikan, siap dicetak.</p><p class="relative mt-2 max-w-xs text-xs leading-relaxed text-brand-100/75">Jadwal dilengkapi legenda jam dan ruang tanda tangan direktur serta kepala seksi.</p><NuxtLink to="/cetak" class="relative mt-5 inline-flex items-center gap-2 rounded-lg bg-lime-soft px-4 py-2 text-xs font-semibold text-brand-800"><Printer :size="15"/>Pratinjau cetak</NuxtLink></section></div>
  </template>
  <section v-else class="panel p-10 text-center"><CalendarDays class="mx-auto mb-4 text-brand-600" :size="30"/><h2 class="text-lg font-semibold">Mulai dengan jadwal pertama</h2><p class="mt-2 text-sm text-slate-500">Tambahkan dokter dan atur jam dinas, lalu pilih bulan yang ingin disusun.</p><button v-if="w.canEdit.value" class="btn btn-primary mt-6" @click="newMonth = true"><Plus :size="16"/>Buat jadwal</button><NuxtLink v-if="w.isAdmin.value" to="/pengaturan" class="btn btn-secondary mt-6 ml-2">Impor data Oktober</NuxtLink></section>
  <NewMonthModal v-if="newMonth" @close="newMonth = false"/>
</template>
